assign_equipment_manager(uuid).def:
CREATE OR REPLACE FUNCTION public.assign_equipment_manager(p_member_id uuid)
 RETURNS equipment_manager
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor  public.members;
  v_target public.members;
  v_row    public.equipment_manager;
begin
  select * into v_actor from public.members where id = public.my_member_id();
  if v_actor.id is null then raise exception 'No member record for the signed-in user'; end if;
  if not public.is_dept_admin() then
    raise exception 'Only a Department Admin can assign equipment managers';
  end if;

  select * into v_target from public.members where id = p_member_id;
  if v_target.id is null then raise exception 'Member not found'; end if;
  if v_target.department_id <> v_actor.department_id then
    raise exception 'Not authorized: that member belongs to another department';
  end if;

  if (select count(*) from public.equipment_manager
        where department_id = v_actor.department_id and removed_at is null) >= 2 then
    raise exception 'A department can have at most two equipment managers. Remove one before assigning another.';
  end if;
  if exists (select 1 from public.equipment_manager
               where department_id = v_actor.department_id and member_id = p_member_id and removed_at is null) then
    raise exception 'That member is already an equipment manager';
  end if;

  insert into public.equipment_manager
    (department_id, member_id, assigned_by, assigned_by_name, assigned_at)
  values
    (v_actor.department_id, p_member_id, v_actor.id, v_actor.name, now())
  returning * into v_row;
  return v_row;
end;
$function$

remove_equipment_manager(uuid).def:
CREATE OR REPLACE FUNCTION public.remove_equipment_manager(p_member_id uuid)
 RETURNS equipment_manager
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.members;
  v_row   public.equipment_manager;
begin
  select * into v_actor from public.members where id = public.my_member_id();
  if v_actor.id is null then raise exception 'No member record for the signed-in user'; end if;
  if not public.is_dept_admin() then
    raise exception 'Only a Department Admin can remove equipment managers';
  end if;

  select * into v_row from public.equipment_manager
    where department_id = v_actor.department_id and member_id = p_member_id and removed_at is null
    for update;
  if v_row.id is null then raise exception 'That member is not an active equipment manager'; end if;

  update public.equipment_manager
     set removed_at = now(), removed_by = v_actor.id, removed_by_name = v_actor.name
   where id = v_row.id
   returning * into v_row;
  return v_row;
end;
$function$

open_signin(uuid).def:
CREATE OR REPLACE FUNCTION public.open_signin(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.training_sessions%rowtype;
  v_token   text;
  v_start   timestamptz;
  v_end     timestamptz;
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to open a sign-in for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from public.my_department_id() then
    raise exception 'That training session was not found in your department.';
  end if;
  if v_session.done then
    raise exception 'This session is complete — you cannot open a sign-in.';
  end if;

  /* THE SIGN-IN WINDOW — see the file header for why both bounds exist and why
     they are asymmetric in intent.

     start_time is nullable: an all-day session with no time reads as midnight,
     so its window opens at midnight the day before. duration_min is nullable
     too: a null duration treats the session as instantaneous, so the window
     still closes 24 hours after its start rather than never.

     Central is hardcoded — see the header. */
  v_start := (v_session.date + coalesce(v_session.start_time, time '00:00'))
               at time zone 'America/Chicago';
  v_end   := v_start + make_interval(mins => coalesce(v_session.duration_min, 0));

  if now() < v_start - interval '24 hours' then
    raise exception 'This training is scheduled for %. Its sign-in can be opened from 24 hours before it starts.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  if now() > v_end + interval '24 hours' then
    raise exception 'This training was scheduled for % and its sign-in window has closed. To record who attended, mark them present on the session''s roster instead.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  -- ---- NEW IN C3 ----
  if v_session.is_offsite
     and (v_session.location_lat is null or v_session.location_lng is null) then
    raise exception 'Set this drill''s location first — you have to be on site, then tap "Use my location".';
  end if;
  -- ---- END NEW ----

  v_token := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
  update public.training_sessions
    set signin_token = v_token, signin_open = true
  where id = p_session_id;
  return v_token;
end;
$function$

close_signin(uuid).def:
CREATE OR REPLACE FUNCTION public.close_signin(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and status in ('Active','Probationary')
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to close this sign-in.';
  end if;
  update public.training_sessions
    set signin_token = null, signin_open = false
  where id = p_session_id and department_id = public.my_department_id();
end;
$function$

move_week(uuid,text).def:
CREATE OR REPLACE FUNCTION public.move_week(p_day_id uuid, p_dir text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept  uuid := public.my_department_id();
  v_me    public.training_sessions;
  v_other public.training_sessions;
begin
  if not public.is_admin() then raise exception 'Only an admin can reorder the schedule.'; end if;
  select * into v_me from public.training_sessions where id = p_day_id and department_id = v_dept;
  if v_me.id is null then raise exception 'That week is no longer on the schedule.'; end if;

  if p_dir = 'up' then
    select * into v_other from public.training_sessions
      where department_id = v_dept and week_number < v_me.week_number
      order by week_number desc limit 1;
  else
    select * into v_other from public.training_sessions
      where department_id = v_dept and week_number > v_me.week_number
      order by week_number asc limit 1;
  end if;
  if v_other.id is null then return 'edge'; end if;   -- already first / last

  -- Swap the two week numbers, and rewrite any leading "Week N" in each title to match.
  update public.training_sessions
     set week_number = v_other.week_number,
         title = regexp_replace(title, '^Week [0-9]+', 'Week ' || v_other.week_number)
   where id = v_me.id;
  update public.training_sessions
     set week_number = v_me.week_number,
         title = regexp_replace(title, '^Week [0-9]+', 'Week ' || v_me.week_number)
   where id = v_other.id;
  return 'ok';
end; $function$

delete_drill_plan(uuid).def:
CREATE OR REPLACE FUNCTION public.delete_drill_plan(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — delete a plan in the caller's OWN department. The session_plans.drill_plan_id FK (ON DELETE SET
  -- NULL) clears its attachments; the per-session plan rows (and their text) are kept.
  declare v_dept uuid := public.my_department_id();
  begin
    if v_dept is null or not coalesce(public.is_canmanage_ops(), false) then
      raise exception 'Only a Department Admin or Officer can delete drill plans.';
    end if;
    delete from public.drill_plans where id = p_id and department_id = v_dept;
    if not found then raise exception 'That drill plan is not in your department.'; end if;
  end;
  $function$

approve_drill_plan(uuid).def:
CREATE OR REPLACE FUNCTION public.approve_drill_plan(p_id uuid)
 RETURNS drill_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — approve a plan in the caller's OWN department. Self-approval allowed (a lesson plan, not a custody
  -- attestation). Already approved: returned unchanged.
  declare v_dept uuid := public.my_department_id(); v_row public.drill_plans;
  begin
    if v_dept is null or not coalesce(public.is_canmanage_ops(), false) then
      raise exception 'Only a Department Admin or Officer can approve drill plans.';
    end if;
    select * into v_row from public.drill_plans where id = p_id and department_id = v_dept for update;
    if not found then raise exception 'That drill plan is not in your department.'; end if;
    if v_row.status = 'approved' then return v_row; end if;
    update public.drill_plans set status = 'approved', approved_by = public.my_member_id(), approved_at = now()
     where id = p_id returning * into v_row;
    return v_row;
  end;
  $function$

current_signin_token(uuid).def:
CREATE OR REPLACE FUNCTION public.current_signin_token(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.training_sessions%rowtype;
begin
  -- ---- gate copied verbatim from open_signin ----
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to open a sign-in for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from public.my_department_id() then
    raise exception 'That training session was not found in your department.';
  end if;
  -- ---- end copied gate ----

  -- No live sign-in, no code. Not an error: the officer's page asks for every
  -- session it is showing, and most of them are legitimately closed.
  if not coalesce(v_session.signin_open, false) then
    return null;
  end if;

  return v_session.signin_token;
end;
$function$

