guard_ai_outputs_session_id().def:
CREATE OR REPLACE FUNCTION public.guard_ai_outputs_session_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept uuid; v_aud text; v_ismtg boolean;
begin
  if new.session_id is null then
    return new;                                   -- un-assigning is always allowed
  end if;
  select department_id, audience, is_meeting into v_dept, v_aud, v_ismtg from public.training_sessions where id = new.session_id;
  if not found or v_dept is distinct from new.department_id then
    raise exception 'That meeting is not in this department';
  end if;
  -- a meeting = a leadership/board session (as before) OR a session a leader flagged "This is a meeting"
  if not (coalesce(v_aud in ('leadership', 'board'), false) or coalesce(v_ismtg, false)) then
    raise exception 'Only a meeting can hold minutes';
  end if;
  return new;
end;
$function$

set_member_termination(uuid,date).def:
CREATE OR REPLACE FUNCTION public.set_member_termination(p_member uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:membership_window — Department Admin of that member's department only. p_date NULL clears it. Never deletes attendance.
declare v_dept uuid; v_me uuid; v_after int := 0;
begin
  select department_id into v_dept from public.members where id = p_member;
  select me.id into v_me from public.members me
   where lower(me.email) = lower(auth.email()) and me.department_id = v_dept
     and me.access && array['Department Admin']::text[]
   limit 1;
  if v_dept is null or v_dept is distinct from public.my_department_id() or v_me is null then
    raise exception 'Only a Department Admin can change this.';
  end if;
  if p_date is null then
    delete from public.member_separation where member_id = p_member;
  else
    insert into public.member_separation as s (member_id, department_id, terminated_on, set_by_member, set_at)
    values (p_member, v_dept, p_date, v_me, now())
    on conflict (member_id) do update set terminated_on = excluded.terminated_on, department_id = excluded.department_id,
                                          set_by_member = excluded.set_by_member, set_at = now();
    select count(*) into v_after from public.session_attendance sa
      join public.training_sessions ts on ts.id = sa.session_id
     where sa.member_id = p_member and ts."date" > p_date;
  end if;
  return jsonb_build_object('terminated_on', p_date, 'attendance_after', v_after);
end;
$function$

set_my_session_registration(uuid,text).def:
CREATE OR REPLACE FUNCTION public.set_my_session_registration(p_session_id uuid, p_status text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:session_registrations — self-only, department-scoped, audience-eligible. Never touches attendance.
declare
  v_me uuid := public.my_member_id();
  v_my_dept uuid := public.my_department_id();
  v_access text[];
  v_sess record;
begin
  if p_status is null or p_status not in ('coming', 'maybe', 'not_coming') then
    raise exception 'Choose Coming, Maybe, or Not coming';
  end if;
  if v_me is null or v_my_dept is null then
    raise exception 'We could not match your login to a member record.';
  end if;
  select department_id, audience, done into v_sess from public.training_sessions where id = p_session_id;
  if not found or v_sess.department_id is distinct from v_my_dept then
    raise exception 'Not in your department';
  end if;
  if coalesce(v_sess.done, false) then
    raise exception 'This session is closed';
  end if;
  select access into v_access from public.members where id = v_me and department_id = v_my_dept;
  if not found then
    raise exception 'Not in your department';
  end if;
  -- audience eligibility — the client's rollFor, server-side
  if v_sess.audience = 'board' and not (coalesce(v_access, '{}') && array['Board Member']::text[]) then
    raise exception 'Not eligible for this session';
  end if;
  if v_sess.audience = 'leadership' and not (coalesce(v_access, '{}') && array['Project Admin', 'Department Admin', 'Board Member', 'Officer']::text[]) then
    raise exception 'Not eligible for this session';
  end if;
  insert into public.session_registrations (session_id, member_id, department_id, status)
  values (p_session_id, v_me, v_my_dept, p_status)
  on conflict (session_id, member_id) do update set status = excluded.status, updated_at = now();
  return p_status;
end;
$function$

attach_drill_plan_to_session(uuid,uuid).def:
CREATE OR REPLACE FUNCTION public.attach_drill_plan_to_session(p_plan_id uuid, p_session_id uuid)
 RETURNS session_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — attach a library plan to a training session in the caller's OWN department, as an ordinary
  -- session_plans row (the existing View plan renders its ai_text). One attachment per (session, plan).
  declare v_dept uuid := public.my_department_id(); v_p public.drill_plans; v_row public.session_plans;
          v_c jsonb; v_who text; L text[] := array[]::text[]; s jsonb; i int := 0;
  begin
    if v_dept is null or not coalesce(public.is_canmanage_ops(), false) then
      raise exception 'Only a Department Admin or Officer can attach drill plans.';
    end if;
    select * into v_p from public.drill_plans where id = p_plan_id and department_id = v_dept for update;
    if not found then raise exception 'That drill plan is not in your department.'; end if;
    if not exists (select 1 from public.training_sessions where id = p_session_id and department_id = v_dept) then
      raise exception 'That session is not in your department.';
    end if;
    if exists (select 1 from public.session_plans where session_id = p_session_id and drill_plan_id = p_plan_id) then
      raise exception 'That plan is already attached to this session.';
    end if;
    v_c := v_p.content;
    -- the Quick Run Sheet, then the full plan — the layout serializeDrillPlan writes and the plan viewer splits on
    L := L || '## Quick Run Sheet'::text;
    if v_p.duration_min is not null then L := L || ''::text || ('Total time: ' || v_p.duration_min || ' min'); end if;
    if jsonb_typeof(v_c -> 'run_of_show') = 'array' then
      for s in select x from jsonb_array_elements(v_c -> 'run_of_show') x loop
        i := i + 1;
        if jsonb_typeof(s) = 'object' then
          L := L || ''::text || ('**' || i || '. ' || coalesce(nullif(s ->> 't', ''), 'Step') || '**');
          if coalesce(s ->> 'd', '') <> '' then L := L || ('- ' || (s ->> 'd')); end if;
        else
          L := L || ''::text || ('**' || i || '. ' || (s #>> '{}') || '**');
        end if;
      end loop;
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '**Safety first:**'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    L := L || ''::text || ('## ' || v_p.title || ' — Drill Plan');
    if coalesce(v_c ->> 'summary', '') <> '' then L := L || ''::text || (v_c ->> 'summary'); end if;
    if v_p.duration_min is not null then L := L || ''::text || ('Duration: ' || v_p.duration_min || ' minutes'); end if;
    if jsonb_typeof(v_c -> 'objectives') = 'array' and jsonb_array_length(v_c -> 'objectives') > 0 then
      L := L || ''::text || '## Objectives'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'objectives') x);
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '## Safety notes'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    if jsonb_typeof(v_c -> 'materials') = 'array' and jsonb_array_length(v_c -> 'materials') > 0 then
      L := L || ''::text || '## Equipment'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'materials') x);
    end if;
    select name into v_who from public.members where id = public.my_member_id();
    insert into public.session_plans (department_id, session_id, title, source, ai_text, created_by, drill_plan_id)
    values (v_dept, p_session_id, v_p.title, 'ai', array_to_string(L, E'\n'), coalesce(v_who, 'Unknown'), p_plan_id)
    returning * into v_row;
    return v_row;
  end;
  $function$

tg_session_attendance_membership_window(.def:
CREATE OR REPLACE FUNCTION public.tg_session_attendance_membership_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:membership_window — refuse attendance on a drill dated outside the member's membership window. No date in the message.
declare v_date date;
begin
  select ts."date" into v_date from public.training_sessions ts where ts.id = NEW.session_id;
  if v_date is not null and not public.membership_window_allows(NEW.member_id, v_date) then
    raise exception 'MEMBERSHIP_WINDOW: this member was not on the department roster on that date.';
  end if;
  return NEW;
end;
$function$

tg_training_session_date_membership_wind.def:
CREATE OR REPLACE FUNCTION public.tg_training_session_date_membership_window()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:membership_window — a drill can't be moved to a date on which one of its recorded attendees was not a member.
begin
  if NEW."date" is distinct from OLD."date" and NEW."date" is not null and exists (
       select 1 from public.session_attendance sa
        where sa.session_id = NEW.id and not public.membership_window_allows(sa.member_id, NEW."date")) then
    raise exception 'MEMBERSHIP_WINDOW: a member recorded at this drill was not on the department roster on that date.';
  end if;
  return NEW;
end;
$function$

set_drill_plan(uuid,text,text,integer,te.def:
CREATE OR REPLACE FUNCTION public.set_drill_plan(p_id uuid, p_title text, p_category text, p_duration_min integer, p_audience text, p_content jsonb, p_source text DEFAULT 'ai'::text)
 RETURNS drill_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — create (p_id null, as a draft) or edit a plan in the caller's OWN department. Edit keeps status + source.
  declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id(); v_row public.drill_plans;
  begin
    if v_dept is null or not coalesce(public.is_canmanage_ops(), false) then
      raise exception 'Only a Department Admin or Officer can manage drill plans.';
    end if;
    if p_title is null or btrim(p_title) = '' then raise exception 'A drill plan needs a title.'; end if;
    if p_content is null or jsonb_typeof(p_content) <> 'object' then raise exception 'A drill plan''s content must be a JSON object.'; end if;
    if p_duration_min is not null and p_duration_min <= 0 then raise exception 'Duration must be a positive number of minutes.'; end if;
    if p_id is null then
      if p_source is null or p_source not in ('ai', 'manual') then raise exception 'A drill plan''s source must be ai or manual.'; end if;
      insert into public.drill_plans (department_id, title, category, duration_min, audience, content, source, created_by, updated_by)
      values (v_dept, btrim(p_title), nullif(btrim(p_category), ''), p_duration_min, nullif(btrim(p_audience), ''), p_content, p_source, v_me, v_me)
      returning * into v_row;
    else
      update public.drill_plans
         set title = btrim(p_title), category = nullif(btrim(p_category), ''), duration_min = p_duration_min,
             audience = nullif(btrim(p_audience), ''), content = p_content, updated_by = v_me, updated_at = now()
       where id = p_id and department_id = v_dept
      returning * into v_row;
      if not found then raise exception 'That drill plan is not in your department.'; end if;
    end if;
    return v_row;
  end;
  $function$

